document.addEventListener("DOMContentLoaded",init);function init(){renderCategoryStrip("category-strip");document.getElementById("search-form").addEventListener("submit",onSearchSubmit);startSearchPrompts();startVoiceSearch();loadHomePageData()}function startVoiceSearch(){const btn=document.getElementById("voice-search-btn");const input=document.getElementById("search-input");const status=document.getElementById("voice-search-status");if(!btn||!input)return;const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition)return;btn.hidden=false;let listening=false;let recognition=null;const say=msg=>{if(status)status.textContent=msg};const stopListening=msg=>{listening=false;btn.classList.remove("is-listening");btn.setAttribute("aria-pressed","false");say(msg||"")};btn.setAttribute("aria-pressed","false");btn.addEventListener("click",()=>{if(listening&&recognition){recognition.abort();stopListening("Stopped listening.");return}recognition=new Recognition;recognition.lang="en-GB";recognition.interimResults=false;recognition.maxAlternatives=1;recognition.addEventListener("start",()=>{listening=true;btn.classList.add("is-listening");btn.setAttribute("aria-pressed","true");say("Listening. Speak in English.")});recognition.addEventListener("result",e=>{const said=(e.results&&e.results[0]&&e.results[0][0]||{}).transcript||"";const q=said.trim();stopListening(q?"Heard: "+q:"");if(!q)return;input.value=q;input.dispatchEvent(new Event("input",{bubbles:true}));document.getElementById("search-form").requestSubmit()});recognition.addEventListener("error",e=>{const why=e&&e.error;if(why==="not-allowed"||why==="service-not-allowed"){stopListening("Microphone blocked. Allow microphone access to search by voice.")}else if(why==="no-speech"){stopListening("Did not catch that.")}else{stopListening("Voice search is not available right now.")}});recognition.addEventListener("end",()=>{if(listening)stopListening("")});try{recognition.start()}catch(err){stopListening("Voice search is not available right now.")}})}const SEARCH_PROMPTS=["What is on your mind?","Ask Mwakete…","Try using Kiribati language."];const SEARCH_PROMPT_MS=3500;function startSearchPrompts(){const input=document.getElementById("search-input");if(!input)return;input.setAttribute("aria-label","Search products, services and rentals");input.placeholder=SEARCH_PROMPTS[0];const reduced=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;if(reduced)return;let i=0;const timer=setInterval(()=>{i=(i+1)%SEARCH_PROMPTS.length;input.placeholder=SEARCH_PROMPTS[i]},SEARCH_PROMPT_MS);const stop=()=>clearInterval(timer);input.addEventListener("focus",stop,{once:true});input.addEventListener("input",stop,{once:true})}function onSearchSubmit(e){e.preventDefault();const q=document.getElementById("search-input").value.trim();window.location.href=`categories.html?q=${encodeURIComponent(q)}`}async function loadHomePageData(){const productsStatusEl=document.getElementById("trending-products-status");const storesStatusEl=document.getElementById("trending-stores-status");const stopProductsLoading=startLoadingMessage(productsStatusEl);const stopStoresLoading=startLoadingMessage(storesStatusEl);const request=Api.get("getHomePageData",{});window.__criticalReady=request;const res=await request;stopProductsLoading();stopStoresLoading();if(!res.ok){showLoadFailedMessage(productsStatusEl);showLoadFailedMessage(storesStatusEl);return}renderTrendingProducts(res.products);renderTrendingStores(res.stores)}function renderTrendingProducts(products){const statusEl=document.getElementById("trending-products-status");const listEl=document.getElementById("trending-products-list");if(products.length===0){statusEl.textContent="No products yet.";return}statusEl.textContent="";listEl.innerHTML=products.map(p=>renderBrowseProductCard(p,{showLocation:true})).join("");dealInCards(listEl);mountBadgeLegend("home-badge-legend",products);recordProductViewsOnce(products.map(p=>p.productId))}const DEAL_INTERVAL_MS=80;function dealInCards(listEl){const cards=Array.prototype.slice.call(listEl.children);if(!cards.length)return;if(window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;cards.forEach(card=>card.classList.add("product-card--dealing"));const fold=window.innerHeight;let delay=0;cards.forEach(card=>{if(card.getBoundingClientRect().top>=fold){card.classList.remove("product-card--dealing");return}setTimeout(()=>card.classList.remove("product-card--dealing"),delay);delay+=DEAL_INTERVAL_MS})}function renderTrendingStores(stores){const statusEl=document.getElementById("trending-stores-status");const listEl=document.getElementById("trending-stores-list");if(stores.length===0){statusEl.textContent="No stores yet.";return}statusEl.textContent="";listEl.innerHTML=stores.map(renderLogoCarouselItem).join("")}